def lcs(string1, string2):
    # Initialize a 2D array to store the LCS lengths for all subproblems
    lengths = [[0] * (len(string2) + 1) for _ in range(len(string1) + 1)]

    # Fill the lengths array based on the rules of the LCS problem
    for i in range(1, len(string1) + 1):
        for j in range(1, len(string2) + 1):
            if string1[i - 1] == string2[j - 1]:
                lengths[i][j] = lengths[i - 1][j - 1] + 1
            else:
                lengths[i][j] = max(lengths[i - 1][j], lengths[i][j - 1])

    # Find the maximum LCS length and the index of the corresponding starting point
    max_length = max(sum(row) for row in lengths)
    starting_point = find_starting_point(lengths, max_length)

    # Generate the LCS and return it
    return generate_lcs(lengths, starting_point, max_length, string1, string2)

# Helper function to find the starting point of the longest common subsequence
def find_starting_point(lengths, max_length):
    for i in range(len(lengths)):
        for j in range(len(lengths[i])):
            if lengths[i][j] == max_length:
                return (i - 1, j - 1)

# Helper function to generate the longest common subsequence based on the starting point and max length
def generate_lcs(lengths, starting_point, max_length, string1, string2):
    lcs = []
    for i in range(max_length):
        # Check if the current character is in the LCS
        if string1[starting_point[0]] == string2[starting_point[1]]:
